import{_ as d,C as i,o as s,c as h,j as t,a as r,E as o,a2 as n}from"./chunks/framework.BFMro0Mr.js";const k=JSON.parse('{"title":"Architecture","description":"How ApiPresenter handles a request in Nette API 3.x - endpoint lookup, rate limit, params, authorization, the handler, output schema check and logging.","frontmatter":{"title":"Architecture","description":"How ApiPresenter handles a request in Nette API 3.x - endpoint lookup, rate limit, params, authorization, the handler, output schema check and logging."},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1793434425000}'),c={name:"guide/architecture.md"};function l(p,e,u,f,m,g){const a=i("Diagram");return s(),h("div",null,[e[0]||(e[0]=t("h1",{id:"architecture",tabindex:"-1"},[r("Architecture "),t("a",{class:"header-anchor",href:"#architecture","aria-label":'Permalink to "Architecture"'},"​")],-1)),e[1]||(e[1]=t("p",null,[r("Every API request goes to one presenter, "),t("code",null,"Tomaj\\NetteApi\\Presenters\\ApiPresenter"),r(". It asks "),t("code",null,"ApiDecider"),r(" which endpoint matches, runs the checks in a fixed order and returns what the handler or the error handler produced.")],-1)),o(a,{name:"architecture-1",alt:"Request, ApiDecider, rate limit, authorization, param error reporting (400), handler, output schema check, response and logger, with 429, 401 and 400 exits and a 404 from DefaultHandler (logged); every response goes back to the client"}),e[2]||(e[2]=n('<h2 id="the-parts" tabindex="-1">The parts <a class="header-anchor" href="#the-parts" aria-label="Permalink to &quot;The parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Class or interface</th><th>Job</th></tr></thead><tbody><tr><td>Presenter</td><td><code>ApiPresenter</code></td><td>Runs every step below. It is <code>final</code>.</td></tr><tr><td>Endpoint list</td><td><code>ApiDecider</code></td><td><code>addApi()</code> registers endpoints, <code>getApi()</code> finds the one for a request.</td></tr><tr><td>Endpoint</td><td><code>EndpointIdentifier</code></td><td>Method, version, package and optional action.</td></tr><tr><td>Handler</td><td><code>ApiHandlerInterface</code>, usually <code>BaseHandler</code></td><td>Declares params and outputs, does the work.</td></tr><tr><td>Authorization</td><td><code>ApiAuthorizationInterface</code></td><td>Says whether the request may run.</td></tr><tr><td>Rate limit</td><td><code>RateLimiterInterface</code></td><td>Optional, per endpoint.</td></tr><tr><td>Errors</td><td><code>ErrorHandlerInterface</code>, <code>DefaultErrorHandler</code></td><td>Turns failures into JSON responses.</td></tr><tr><td>Output checks</td><td><code>ConfiguratorInterface</code></td><td>Decides whether outputs are validated and error details shown.</td></tr><tr><td>Logger</td><td><code>ApiLoggerInterface</code></td><td>Optional, found in the DI container.</td></tr></tbody></table><h2 id="the-order-of-the-steps" tabindex="-1">The order of the steps <a class="header-anchor" href="#the-order-of-the-steps" aria-label="Permalink to &quot;The order of the steps&quot;">​</a></h2><p>In short: CORS headers, endpoint lookup (<code>404</code>), rate limit (<code>429</code>), params are read, authorization (<code>401</code>), param errors (<code>400</code>), the handler, the output check (<code>500</code>) and logging. Params are read before authorization, but their errors are reported only after it, so a caller without access gets <code>401</code> and no details about the params.</p><p>The full order, with the code and the exit of every step, is on one page: <a href="/nette-api/pr-preview/pr-238/guide/presenter.html">ApiPresenter pipeline</a>.</p>',5)),o(a,{name:"architecture-2",alt:"Sequence of a POST request: authorization, then param errors (read before it) and the handler, each with its error branch through the error handler"}),e[3]||(e[3]=n('<div class="warning custom-block"><p class="custom-block-title">Not every response is logged</p><p>The rate limit, authorization and param error steps return early, so <code>429</code>, <code>401</code>, <code>400</code> and the <code>500</code> of a failing authorization never reach the logger in 3.x. <code>404</code>, handler responses and handler or output errors are logged.</p></div><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="can-i-replace-apipresenter-with-my-own-presenter" tabindex="-1">Can I replace ApiPresenter with my own presenter? <a class="header-anchor" href="#can-i-replace-apipresenter-with-my-own-presenter" aria-label="Permalink to &quot;Can I replace ApiPresenter with my own presenter?&quot;">​</a></h3><p>Not by extending it, the class is <code>final</code>. You can configure it (<code>setCorsHeader()</code>) and swap its dependencies: the error handler, the configurator and the logger. See <a href="/nette-api/pr-preview/pr-238/guide/errors.html">Error handling</a>.</p><h3 id="why-does-a-request-with-a-wrong-token-and-wrong-params-answer-401-not-400" tabindex="-1">Why does a request with a wrong token and wrong params answer 401, not 400? <a class="header-anchor" href="#why-does-a-request-with-a-wrong-token-and-wrong-params-answer-401-not-400" aria-label="Permalink to &quot;Why does a request with a wrong token and wrong params answer 401, not 400?&quot;">​</a></h3><p>Authorization runs before param errors are reported. See step 6 above and <a href="/nette-api/pr-preview/pr-238/guide/authorization.html">Authorization</a>.</p><h3 id="is-the-handler-created-for-every-endpoint-on-every-request" tabindex="-1">Is the handler created for every endpoint on every request? <a class="header-anchor" href="#is-the-handler-created-for-every-endpoint-on-every-request" aria-label="Permalink to &quot;Is the handler created for every endpoint on every request?&quot;">​</a></h3><p>No. When you pass a class name to <code>addApi()</code>, the handler is taken from the DI container only when its endpoint is called. See <a href="/nette-api/pr-preview/pr-238/guide/handlers.html#registering-a-handler">Handlers</a>.</p><h3 id="what-does-the-response-of-an-unknown-endpoint-look-like" tabindex="-1">What does the response of an unknown endpoint look like? <a class="header-anchor" href="#what-does-the-response-of-an-unknown-endpoint-look-like" aria-label="Permalink to &quot;What does the response of an unknown endpoint look like?&quot;">​</a></h3><p><code>404</code> with <code>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;Unknown api endpoint&quot;}</code>. The <a href="/nette-api/pr-preview/pr-238/examples/hello-world.html">hello world example</a> tests it.</p><h3 id="where-do-i-see-all-the-classes-in-one-list" tabindex="-1">Where do I see all the classes in one list? <a class="header-anchor" href="#where-do-i-see-all-the-classes-in-one-list" aria-label="Permalink to &quot;Where do I see all the classes in one list?&quot;">​</a></h3><p>In the <a href="/nette-api/pr-preview/pr-238/api/reference.html">Reference</a>.</p>',12))])}const q=d(c,[["render",l]]);export{k as __pageData,q as default};
